// This test expect that the repository defined in UNIT_TEST_DOCKER_IMAGE is in zstd format.
// the repository is built by the 01_simple_docker.sh integration test fileHelper.
// This test also require root. At the moment, unpacking docker images with 'img' requires root permission to
// mount/unmount layers.
var _ = Describe("Docker client", func() {
	Context("With repository", func() {
		ctx := context.NewContext()

		repoImage := os.Getenv("UNIT_TEST_DOCKER_IMAGE")
		var repoURL []string
		var c *DockerClient
		BeforeEach(func() {
			if repoImage == "" {
				Skip("UNIT_TEST_DOCKER_IMAGE not specified")
			}
			repoURL = []string{repoImage}
			c = NewDockerClient(RepoData{Urls: repoURL}, ctx)
		})

		It("Downloads single files", func() {
			f, err := c.DownloadFile("repository.yaml")
			Expect(err).ToNot(HaveOccurred())
			Expect(fileHelper.Read(f)).To(ContainSubstring("Test Repo"))
			os.RemoveAll(f)
		})

		It("Downloads artifacts", func() {
			f, err := c.DownloadArtifact(&artifact.PackageArtifact{
				Path: "test.tar",
				CompileSpec: &types.LuetCompilationSpec{
					Package: &types.Package{
						Name:     "c",
						Category: "test",
						Version:  "1.0",
					},
				},
			})
			Expect(err).ToNot(HaveOccurred())
			tmpdir, err := os.MkdirTemp("", "test")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(tmpdir) // clean up

			Expect(f.Unpack(ctx, tmpdir, false)).ToNot(HaveOccurred())
			Expect(fileHelper.Read(filepath.Join(tmpdir, "c"))).To(Equal("c\n"))
			Expect(fileHelper.Read(filepath.Join(tmpdir, "cd"))).To(Equal("c\n"))
			os.RemoveAll(f.Path)
		})
	})

	// Regression tests for https://github.com/mudler/luet/issues/386
	//
	// When every configured repository failed, DownloadArtifact returned
	// (nil, nil): the download error was captured by a loop-scoped `err`, so
	// the function-scoped one was still nil, and errors.Wrap(nil, ...) returns
	// nil. Callers check the error and then dereference the artifact, so
	// installer.getPackage panicked on a nil *PackageArtifact.
	//
	// These need no registry: the URLs are deliberately unreachable.
	Context("When every repository fails", func() {
		ctx := context.NewContext()
		unreachable := RepoData{Urls: []string{"127.0.0.1:1/nonexistent"}}

		It("returns an error rather than a nil artifact with a nil error", func() {
			c := NewDockerClient(unreachable, ctx)

			a, err := c.DownloadArtifact(&artifact.PackageArtifact{
				Path: "test.tar",
				CompileSpec: &types.LuetCompilationSpec{
					Package: &types.Package{
						Name:     "c",
						Category: "test",
						Version:  "1.0",
					},
				},
			})

			// The contract: a nil artifact MUST be accompanied by an error,
			// otherwise callers dereference nil.
			Expect(err).To(HaveOccurred())
			Expect(a).To(BeNil())
		})

		It("returns an error rather than an empty path with a nil error", func() {
			c := NewDockerClient(unreachable, ctx)

			f, err := c.DownloadFile("repository.yaml")

